import re

def normalize_path(path):
    """Replace valid {variable_name} patterns with {var}"""
    return re.sub(r'\{[a-zA-Z0-9_-]+\}', '{var}', path)

def is_valid_method(method):
    return method.upper() in ('GET', 'POST', 'PUT', 'DELETE', 'PATCH')

def is_valid_permission(perm):
    return perm.upper() in ('ALLOW', 'DENY')

def is_valid_role(role):
    return bool(re.match(r'^[a-zA-Z0-9_-]+$', role))

def is_proper_path_prefix(prefix, path):
    """Check if prefix is a proper path prefix of path (not equal)"""
    if prefix == path:
        return False
    if not path.startswith(prefix):
        return False
    if len(prefix) > 0 and prefix[-1] == '/':
        return True
    return len(path) > len(prefix) and path[len(prefix)] == '/'

def is_path_starts_with(prefix, path):
    """Check if path starts with prefix (path prefix match, including equality)"""
    if prefix == path:
        return True
    return is_proper_path_prefix(prefix, path)

